export class ObservationWriter {
  constructor({ path, laneRunId, now = () => new Date().toISOString() }) {
    this.path = path;
    this.laneRunId = requiredString(laneRunId, "laneRunId");
    this.now = now;
    this.sequence = 0;
    this.initialized = false;
  }

  async initialize({ append = false } = {}) {
    await mkdir(dirname(this.path), { recursive: true });
    if (!append) await writeFile(this.path, "", "utf8");
    this.initialized = true;
  }

  async record(milestone, type, fields = {}) {
    if (!this.initialized) throw new Error("observation writer must be initialized");
    this.sequence += 1;
    const event = normalizeObservationEvent({
      version: OBSERVATION_VERSION,
      laneRunId: this.laneRunId,
      milestone,
      sequence: this.sequence,
      at: this.now(),
      type,
      ...fields,
    });
    await appendFile(this.path, `${JSON.stringify(event)}\n`, "utf8");
    return event;
  }

  claim(milestone, block, { owner = null } = {}) {
    return this.record(milestone, "block-claim", {
      block,
      owner,
      claimed: true,
      reason: null,
    });
  }

  nonClaim(
    milestone,
    block,
    reason = NON_CLAIM_REASONS[block],
    { owner = null } = {},
  ) {
    return this.record(milestone, "block-claim", {
      block,
      owner,
      claimed: false,
      reason,
    });
  }

  restart(milestone) {
    return this.record(milestone, "lifecycle", { operation: "restart", destructive: false });
  }

  reseed(milestone, { destructive = false } = {}) {
    return this.record(milestone, "lifecycle", { operation: "reseed", destructive });
  }

  assertionWait(milestone, fields) {
    return this.record(milestone, "assertion-wait", fields);
  }

  semanticAction(milestone, fields) {
    return this.record(milestone, "semantic-action", fields);
  }

  recoveryEpisode(milestone, fields) {
    return this.record(milestone, "recovery-episode", fields);
  }

  apiRequest(milestone, fields) {
    return this.record(milestone, "api-request", fields);
  }
}

export class HostLoadSampler {
  constructor({ writer, milestone, ceilings, intervalMs = 60_000, sample = loadavg }) {
    if (!(writer instanceof ObservationWriter)) {
      throw new TypeError("HostLoadSampler.writer must be an ObservationWriter");
    }
    this.writer = writer;
    this.milestone = milestone;
    this.ceilings = {
      loadavg1: requiredNumber(ceilings?.loadavg1, "ceilings.loadavg1"),
      loadavg5: requiredNumber(ceilings?.loadavg5, "ceilings.loadavg5"),
    return this.writer.restart(milestone);
  }

  reseed(milestone, options) {
    return this.writer.reseed(milestone, options);
  }

  semanticAction(milestone, event) {
    return this.writer.semanticAction(milestone, event);
  }

  recoveryEpisode(milestone, event) {
    return this.writer.recoveryEpisode(milestone, event);
  }

  async suiteAssertionWait(milestone, fields, waitForSettlement) {
    if (typeof waitForSettlement !== "function") {
      throw new TypeError(
        "LaneObservationHarness.suiteAssertionWait requires a settlement-wait function",
      );
    }
    const started = performance.now();
    let pass = false;
    try {
      const result = await waitForSettlement();
      pass = result?.pass !== false;
      return result;
    } finally {
      await this.writer.assertionWait(milestone, {
        ...fields,
        owner: "suite",
        durationMs: performance.now() - started,
        pass,
      });
    }
  }

  suiteAssertionObservation(milestone, fields) {
    return this.writer.assertionWait(milestone, {
      ...fields,
      owner: "suite",
    });
  }

  async apiRequest(milestone, fields, operation) {
    if (typeof operation !== "function") {
      throw new TypeError("LaneObservationHarness.apiRequest requires an operation function");
    }
    try {
      const result = await operation();
      await this.writer.apiRequest(milestone, { ...fields, outcome: "success" });
      return result;
    } catch (error) {
      await this.writer.apiRequest(milestone, { ...fields, outcome: "error" });
      throw error;
    }
      operation: "launch-native-cell",
      requestId: `launch-${config.cell.id}`,
      retryOf: null,
    }, () => launchHarness(state));
    await controls.semanticAction({
      actionId: `native-${milestone.toLowerCase()}-${++state.actionSequence}`,
      actionClass: "process",
      disposition: "progress",
      episodeId: null,
      retriedClass: null,
      binaryExcavation: false,
    });
  }
  const marker = await waitForMarker(state, milestone);
  state.suiteStatusPath = marker.suiteStatus ?? state.suiteStatusPath;
  for (const [suffix, path] of [
    ["suite", marker.suiteObservations],
    ["choreography", marker.choreographyObservations],
  ]) {
    if (path) {
      state.observationSources.push({
        sourceId: `${milestone.toLowerCase()}-${suffix}-observations`,
        path,
      });
    }
  }
  await state.observationQueue;
  if (marker.status === "green" && (!marker.suiteObservations || !marker.choreographyObservations)) {
    throw new Error(`${milestone} green signal lacks suite/choreography observation sidecars`);
  }
  if (milestone === config.milestones.at(-1)) {
    const exit = await state.exit;
    if (exit.error || exit.code !== 0) {
      throw new Error(
        `native ${config.cell.harness} CLI exited ${exit.error ?? exit.code ?? exit.signal}`,
      );
    }
  }
}

export async function finalize({ config, error }) {
  const state = states.get(config.laneRunId);
  if (!state) throw new Error("R2 production driver was not prepared");
  if (error && state.child && state.child.exitCode === null && state.child.signalCode === null) {
    state.child.kill("SIGTERM");
    await state.closed;
  }
  await writeTerminalArtifacts(state, error);
}

export function observationSources({ config }) {
  const state = states.get(config.laneRunId);
  return state?.observationSources ?? [];
}

