  const author = await ctx.db.get('users', post.authorId);
  if (!author) throw new Error('post author missing');
  const likes = await ctx.db
    .query('likes')
    .withIndex('by_post')
    .eq('postId', post._id)
    .take(1024)
    .collect();
  const reposts = await ctx.db
    .query('reposts')
    .withIndex('by_post')
    .eq('postId', post._id)
    .take(1024)
    .collect();
  const replies = await ctx.db
    .query('posts')
    .withIndex('by_parent_created')
    .eq('parentId', post._id)
    .take(1024)
    .collect();
  return {
    entryId: repostedByName ? `repost:${repostedByName}:${post._id}:${sortAt}` : `post:${post._id}`,
    postId: post._id,
    externalId: post.externalId,
    authorId: author._id,
