export const markRead = defineJsMutation({
  args: { conversationId: v.id('conversations') },
  auth: 'authenticated',
  writes: ['receipts'],
  refusals: ['PROFILE_REQUIRED', 'NOT_A_MEMBER'],
  result: results.value(v.object({ updated: v.integer() })),
  handler: async (ctx, args) => {
    const { user } = await requireActiveMembership(ctx, args.conversationId);
    const rows = await ctx.db.query('receipts').withIndex('by_user_conversation').eq('userId', user._id).eq('conversationId', args.conversationId).take(1024).collect();
    let updated = 0;
    const now = ctx.runtime.now();
    for (const row of rows) {
      if (row.required && row.state < 2) {
        await ctx.db.patch('receipts', row._id, { state: 2, updatedAt: now });
        updated += 1;
      }
    }
    return { updated };
  },
});

export const conversationsForMe = defineJsLiveQuery({
  args: {},
  auth: 'authenticated',
  reads: ['users', 'conversations', 'memberships', 'receipts'],
  refusals: ['PROFILE_REQUIRED'],
  result: results.records(v.object({
    id: v.id('conversations'),
    externalId: v.string(),
    kind: v.union([v.literal('dm'), v.literal('group')]),
    title: v.string(),
    description: v.string(),
    avatarUri: v.string(),
    lastPreview: v.string(),
    updatedAt: v.integer(),
    unreadCount: v.integer(),
  }), { minItems: 0, maxItems: 200 }),
  handler: async (ctx) => {
    const user = await requireCurrentUser(ctx);
    const mine = await ctx.db.query('memberships').withIndex('by_user').eq('userId', user._id).take(200).collect();
    const rows = [];
    for (const membership of mine) {
      if (!membership.active) continue;
      const conversation = await ctx.db.get('conversations', membership.conversationId);
      if (!conversation) continue;
      let title = conversation.name;
      let avatarUri = '';
      if (conversation.kind === 'dm') {
        const memberships = await ctx.db.query('memberships').withIndex('by_conversation').eq('conversationId', conversation._id).take(2).collect();
        const otherMembership = memberships.find((entry) => entry.userId !== user._id);
        const other = otherMembership ? await ctx.db.get('users', otherMembership.userId) : null;
        title = other?.displayName ?? 'Direct message';
        avatarUri = other?.avatarUri ?? '';
      }
      const receipts = await ctx.db.query('receipts').withIndex('by_user_conversation').eq('userId', user._id).eq('conversationId', conversation._id).take(1024).collect();
      rows.push({
        id: conversation._id,
        externalId: conversation.externalId,
        kind: conversation.kind,
        title,
        description: conversation.description,
        avatarUri,
        lastPreview: conversation.lastPreview,
        updatedAt: conversation.updatedAt,
        unreadCount: receipts.filter((receipt) => receipt.required && receipt.state < 2).length,
      });
    }
    rows.sort((a, b) => b.updatedAt - a.updatedAt);
    return rows;
  },
});

export const conversationMessages = defineJsLiveQuery({
  args: { conversationId: v.id('conversations') },
  auth: 'authenticated',
  reads: ['users', 'conversations', 'memberships', 'messages', 'receipts'],
  refusals: ['PROFILE_REQUIRED', 'NOT_A_MEMBER'],
  result: results.records(v.object({
    id: v.id('messages'),
    externalId: v.string(),
    conversationId: v.id('conversations'),
    senderId: v.id('users'),
    senderName: v.string(),
    senderAvatarUri: v.string(),
    text: v.string(),
    createdAt: v.integer(),
    quoteMessageId: v.string(),
    quoteExternalId: v.string(),
    quoteSenderName: v.string(),
    quoteExcerpt: v.string(),
    receipt: v.union([v.literal('sent'), v.literal('delivered'), v.literal('read')]),
    mine: v.boolean(),
  }), { minItems: 0, maxItems: 1024 }),
  handler: async (ctx, args) => {
    const user = await requireCurrentUser(ctx);
    const membership = await ctx.db.query('memberships').withIndex('by_conversation_user').eq('conversationId', args.conversationId).eq('userId', user._id).first();
    if (!membership) ctx.refuse('NOT_A_MEMBER');
    const messages = await ctx.db.query('messages').withIndex('by_conversation_created').eq('conversationId', args.conversationId).order('createdAt', 'asc').take(1024).collect();
    const visible = membership.active ? messages : messages.filter((message) => message.createdAt <= membership.leftAt);
    const rows = [];
    for (const message of visible) {
      const sender = await ctx.db.get('users', message.senderId);
      if (!sender) continue;
      const quote = message.quoteMessageId ? await ctx.db.get('messages', message.quoteMessageId) : null;
      const quoteSender = quote ? await ctx.db.get('users', quote.senderId) : null;
      const receipts = await ctx.db.query('receipts').withIndex('by_message').eq('messageId', message._id).take(50).collect();
      const required = receipts.filter((receipt) => receipt.required);
      const receipt = required.length > 0 && required.every((entry) => entry.state >= 2)
        ? 'read'
        : required.length > 0 && required.every((entry) => entry.state >= 1)
          ? 'delivered'
          : 'sent';
      rows.push({
        id: message._id,
        externalId: message.externalId,
        conversationId: message.conversationId,
        senderId: message.senderId,
        senderName: sender.displayName,
        senderAvatarUri: sender.avatarUri,
        text: message.text,
        createdAt: message.createdAt,
        quoteMessageId: quote?._id ?? '',
        quoteExternalId: quote?.externalId ?? '',
        quoteSenderName: quoteSender?.displayName ?? '',
        quoteExcerpt: quote?.text.slice(0, 120) ?? '',
        receipt,
        mine: message.senderId === user._id,
      });
    }
    return rows;
  },
});

