export default function ProfileRoute() {
  const params = useLocalSearchParams<{ handle: string }>();
  const router = useRouter();
  const me = useSnapbackQuery(api.currentUser, {});
  const resolvedHandle = params.handle === 'me' ? me.data?.[0]?.handle : params.handle;
  const profile = useSnapbackQuery(api.profileByHandle, resolvedHandle ? { handle: resolvedHandle } : skip);
  const setFollow = useSnapbackMutation(api.setFollow, { queue: false });
  const row = profile.data?.[0];
  if (!row) return <Text style={styles.loading}>Loading profile…</Text>;

  return (
    <ScrollView contentContainerStyle={styles.page}>
