          followingCount={row.followingCount}
          handle={row.handle}
          link={row.link}
          location={row.location}
          mode="view-own"
          onPressEdit={() => router.push('/profile/edit')}
          onPressLink={(url) => void Linking.openURL(url)}
        />
      ) : (
        <ProfileForm
