function displayTime(value: number): string {
  const seconds = Math.max(0, Math.floor((Date.now() - value) / 1000));
  if (seconds < 60) return 'now';
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m`;
  if (seconds < 86400) return `${Math.floor(seconds / 3600)}h`;
  return `${Math.floor(seconds / 86400)}d`;
}

export function FeedScreen() {
  const router = useRouter();
  const [tab, setTab] = useState<FeedTab>('following');
  const [pageSize, setPageSize] = useState(20);
  const [draft, setDraft] = useState('');
  const [error, setError] = useState<string | null>(null);
  const feed = useSnapbackQuery(api.feed, { tab: tab === 'trending' ? 'global' : tab, limit: pageSize, before: 0 });
  const chats = useSnapbackQuery(api.conversationsForMe, {});
  const createPost = useSnapbackMutation(api.createPost, { queue: false });
  const setLike = useSnapbackMutation(api.setLike, { queue: false });
  const setRepost = useSnapbackMutation(api.setRepost, { queue: false });
  const rows = tab === 'trending' ? [] : (feed.data ?? []) as readonly FeedRow[];

  const publish = async (text: string) => {
    const body = text.trim();
    if (!body) return;
    setError(null);
    try {
      await createPost({ externalId: mutationId('post'), kind: 'text', text: body, imageUris: [], videoUri: '' });
      setDraft('');
    } catch (cause) {
      setError(errorMessage(cause));
    }
  };

  const renderPost = ({ item }: Readonly<{ item: FeedRow }>) => (
    <FeedCard
