      onPressMedia={() => {}}
      onPressReply={() => router.push(`/thread/${item.postId}`)}
      onPressRepost={() => void setRepost({ postId: item.postId, state: !item.reposted, mutationId: mutationId('repost') })}
      replyCount={item.replyCount}
      repostCount={item.repostCount}
      reposted={item.reposted}
      repostedByName={item.repostedByName || undefined}
      text={item.text}
      timestamp={displayTime(item.createdAt)}
      videoUri={item.kind === 'video' ? item.videoUri : undefined}
    />
  );

  return (
    <SafeAreaView style={styles.safe}>
      <View style={styles.header}>
        <View><Text style={styles.wordmark}>Clique</Text><Text style={styles.subtitle}>Your people, in the moment.</Text></View>
        <View style={styles.nav}>
          <Pressable accessibilityRole="button" onPress={() => router.push('/chats')} style={styles.navButton}><Text style={styles.navText}>Chats</Text></Pressable>
          <Pressable accessibilityRole="button" onPress={() => router.push('/profile/me')} style={styles.navButton}><Text style={styles.navText}>Profile</Text></Pressable>
          <Pressable accessibilityRole="button" onPress={() => router.push('/settings')} style={styles.navButton}><Text style={styles.navText}>Settings</Text></Pressable>
        </View>
      </View>
      <FeedTabs active={tab} onChange={(next) => { setTab(next); setPageSize(20); }} />
      {tab === 'trending' ? (
        <View style={styles.empty}><Text style={styles.emptyTitle}>Trending arrives in a later milestone.</Text></View>
      ) : (
        <FlatList
          ListHeaderComponent={(
            <View>
              {(chats.data as readonly ChatPreviewRow[] | undefined)?.slice(0, 4).map((chat) => (
                <ChatListRow
                  avatarUri={chat.avatarUri || undefined}
                  key={chat.id}
                  onPress={() => router.push({ pathname: '/conversation/[id]', params: { id: chat.id, title: chat.title } })}
                  preview={chat.lastPreview}
                  title={chat.title}
                  unreadCount={chat.unreadCount}
                />
              ))}
              <Composer maxLength={500} onChangeText={setDraft} onSend={(text) => void publish(text)} value={draft} variant="post" />
              {error ? <Text style={styles.error}>{error}</Text> : null}
            </View>
          )}
          contentContainerStyle={styles.list}
          data={rows}
          keyExtractor={(item) => item.entryId}
          onEndReached={() => { if (rows.length >= pageSize && pageSize < 100) setPageSize((value) => Math.min(100, value + 20)); }}
          onEndReachedThreshold={0.4}
          renderItem={renderPost}
        />
      )}
    </SafeAreaView>
  );
}

